"""Auto-generated model card with data hash, plan, results and eval gate outcome."""

from __future__ import annotations

from pathlib import Path
from typing import Any


def render_model_card(run: dict[str, Any], lineage: dict[str, Any]) -> str:
    spec, plan, res = run.get("spec") or {}, run.get("plan") or {}, run.get("result") or {}
    sim = bool(run.get("simulated"))
    lines = [f"# {spec.get('name', run['id'])}", ""]
    if sim:
        lines += ["> **SIMULATED RUN: no model was trained. This card documents a dry run only.**", ""]
    lines += [
        f"- Base model: `{(spec.get('model') or {}).get('base', '?')}`",
        f"- Run id: `{run['id']}`  |  engine: `{run.get('engine')}`  |  status: `{run.get('status')}`",
        f"- Training data hash: `{lineage.get('data_hash') or 'n/a'}`",
        f"- Method: {plan.get('method')} ({plan.get('precision')}), micro-batch {plan.get('micro_batch')} x "
        f"accum {plan.get('grad_accum')}, lr {plan.get('learning_rate')}, epochs {plan.get('epochs')}",
        f"- Steps: {res.get('steps')} | final loss: {res.get('final_loss')} | eval loss: {res.get('eval_loss')}",
    ]
    if res.get("peak_gb") is not None:
        lines.append(f"- Peak GPU memory: {res['peak_gb']} GB | throughput: {res.get('tokens_per_s')} tok/s")
    if lineage.get("evals"):
        lines += ["", "## Evaluation"]
        for e in lineage["evals"]:
            lines.append(f"- **{e['name']}**: `{e['result']}`")
    if lineage.get("artifacts"):
        lines += ["", "## Artifacts"]
        lines += [f"- {a['kind']}: `{a['path']}` (sha256 {a['sha256']})" for a in lineage["artifacts"]]
    lines += ["", "_Generated by Bitstraining. Reported numbers come from this run's own logs; "
              "they are not benchmarks._"]
    return "\n".join(lines) + "\n"


def write_model_card(run: dict[str, Any], lineage: dict[str, Any], dest: str | Path) -> Path:
    p = Path(dest)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(render_model_card(run, lineage))
    return p
